title Customer Return Process

start

:Receive return request and item;
:Verify proof of purchase;

if (Receipt valid & within policy period?) then (yes)
  :Inspect item condition;
  if (Item in acceptable condition?) then (yes)
    :Determine refund method\n(original payment / store credit);
    :Issue refund;
    :Restock or route to inventory;
    :Send confirmation to customer;
  else (no)
    :Mark return as rejected\n(damaged or altered);
    :Explain reason to customer;
    :Return item to customer;
  endif
else (no)
  :Reject return\n(invalid receipt or expired);
  :Explain policy to customer;
endif

stop
@enduml

