{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "A bar chart showing fruit sales.",
  "width": 400,
  "height": 250,
  "padding": 5,

  "data": [
    {
      "name": "table",
      "values": [
        {"category": "Apples", "amount": 28},
        {"category": "Pears", "amount": 55},
        {"category": "Plums", "amount": 43}
      ]
    }
  ],

  "scales": [
    {
      "name": "xscale",
      "type": "band",
      "domain": {"data": "table", "field": "category"},
      "range": "width",
      "padding": 0.2
    },
    {
      "name": "yscale",
      "type": "linear",
      "domain": {"data": "table", "field": "amount"},
      "range": "height",
      "nice": true,
      "zero": true
    }
  ],

  "axes": [
    {"orient": "bottom", "scale": "xscale", "title": "Fruit"},
    {"orient": "left", "scale": "yscale", "title": "Sales"}
  ],

  "marks": [
    {
      "type": "rect",
      "from": {"data": "table"},
      "encode": {
        "enter": {
          "x": {"scale": "xscale", "field": "category"},
          "width": {"scale": "xscale", "band": 1},
          "y": {"scale": "yscale", "field": "amount"},
          "y2": {"scale": "yscale", "value": 0},
          "fill": {"value": "#4c78a8"},
          "cornerRadiusTopLeft": {"value": 4},
          "cornerRadiusTopRight": {"value": 4}
        },
        "update": {
          "fillOpacity": {"value": 1}
        },
        "hover": {
          "fillOpacity": {"value": 0.75}
        }
      }
    }
  ]
}

